using EnterpriseDocumentIntelligence.BuildingBlocks.Domain;
public sealed record DocumentCreateCommand(Guid TenantId,string Name,string ContentType,long SizeBytes,string BlobUri,string Sha256);
public static class DocumentRules{public const long MaxSizeBytes=524288000;public static readonly IReadOnlySet<string> AllowedContentTypes=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"application/pdf","text/plain","application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/msword"};public static void Validate(DocumentCreateCommand c){if(c.TenantId==Guid.Empty)throw new UnauthorizedAccessException("Tenant is required");if(string.IsNullOrWhiteSpace(c.Name))throw new ArgumentException("Name is required",nameof(c.Name));if(c.SizeBytes<=0||c.SizeBytes>MaxSizeBytes)throw new ArgumentOutOfRangeException(nameof(c.SizeBytes));if(!AllowedContentTypes.Contains(c.ContentType))throw new ArgumentException("Unsupported document type",nameof(c.ContentType));if(string.IsNullOrWhiteSpace(c.BlobUri))throw new ArgumentException("Blob URI is required",nameof(c.BlobUri));if(string.IsNullOrWhiteSpace(c.Sha256))throw new ArgumentException("SHA-256 is required",nameof(c.Sha256));}public static (Document Document,DocumentVersion Version) Create(DocumentCreateCommand c){Validate(c);var d=new Document(c.TenantId,c.Name,c.ContentType,c.SizeBytes);var v=new DocumentVersion(d.Id,1,c.BlobUri,c.Sha256,c.SizeBytes);d.Versions.Add(v);d.SetCurrentVersion(v.Id);d.MarkProcessing();return(d,v);}}